import test from 'node:test';
import assert from 'node:assert/strict';

import { runBatch, concurrency } from '../acceptance/catcher-pair/worker.mjs';
import { acquireBatch, capacity } from '../acceptance/catcher-pair/pool.mjs';

test('runBatch serves every configured worker immediately (no throw)', () => {
  assert.doesNotThrow(
    () => runBatch(),
    (err) => {
      // Ensure failures include marker for the harness.
      assert.fail(`OSMOGREP_REGRESSION: runBatch unexpectedly threw: ${err && err.message}`);
    },
  );

  const got = runBatch();
  assert.equal(
    got.length,
    concurrency,
    `OSMOGREP_REGRESSION: runBatch should return ${concurrency} items, got ${got.length} (capacity=${capacity})`,
  );
});

test('acquireBatch rejects requests over capacity', () => {
  assert.throws(
    () => acquireBatch(capacity + 1),
    /capacity exhausted/,
    `OSMOGREP_REGRESSION: acquireBatch should throw when count > capacity (capacity=${capacity})`,
  );
});
